<template>
  <view class="page"><jk-page-nav title="库存盘点"/><view class="content"><view class="intro"><view><text>库存盘点</text><small>区县代理可盘点本人库存账户</small></view><button @tap="create">新建盘点</button></view><view v-for="item in list" :key="item.id" class="card" @tap="open(item)"><view class="head"><text>{{item.checkNo}}</text><jk-status-tag :text="statusText(item.status)" :tone="tone(item.status)"/></view><view class="metrics"><view><text>账面</text><strong>{{item.bookTotalQty||0}}</strong></view><view><text>实盘</text><strong>{{item.actualTotalQty||0}}</strong></view><view><text>盘盈</text><strong>{{item.profitQty||0}}</strong></view><view><text>盘亏</text><strong>{{item.lossQty||0}}</strong></view></view><view class="time">{{item.createTime}}</view></view><jk-empty v-if="loaded&&!list.length" text="暂无盘点记录"/></view></view>
</template>
<script>
import JkPageNav from '@/components/jk/jk-page-nav.vue';import JkStatusTag from '@/components/jk/jk-status-tag.vue';import JkEmpty from '@/components/jk/jk-empty.vue';import{getJkMyStock}from'@/api/jk.js';import{createJkStockCheck,getJkStockCheckList}from'@/api/jkV31.js';
export default{components:{JkPageNav,JkStatusTag,JkEmpty},data(){return{list:[],loaded:false,stockAccountId:null}},onShow(){this.load();this.resolveAccount()},methods:{value(r){return(r&&r.data)||r||{}},load(){this.loaded=false;getJkStockCheckList({page:1,limit:50}).then(r=>{const d=this.value(r);this.list=d.list||d.records||[]}).finally(()=>this.loaded=true)},resolveAccount(){getJkMyStock().then(r=>{const d=this.value(r),rows=Array.isArray(d)?d:(d.list||d.items||[]);const first=rows[0]||{};this.stockAccountId=first.stockAccountId||first.accountId||null})},create(){if(!this.stockAccountId)return uni.showToast({title:'未找到本人库存账户',icon:'none'});uni.showModal({title:'创建盘点',content:'创建后请进入详情填写全部实盘数量；提交后库存账户将冻结，等待后台审核。',success:r=>{if(r.confirm)createJkStockCheck({requestNo:'SC-'+Date.now(),stockAccountId:this.stockAccountId,scopeType:'ACCOUNT',remark:'本人发起库存盘点'}).then(res=>{const d=this.value(res);uni.navigateTo({url:'/pages/jk/stockCheck/detail?id='+d.id})})}})},open(i){uni.navigateTo({url:'/pages/jk/stockCheck/detail?id='+i.id})},statusText(s){return{DRAFT:'待实盘',SUBMITTED:'待审核',COMPLETED:'已完成',REJECTED:'已驳回'}[s]||s},tone(s){return s==='COMPLETED'?'success':s==='SUBMITTED'?'warning':s==='REJECTED'?'danger':'info'}}}
</script>
<style scoped>.page{min-height:100vh;background:#f7f9f9}.content{padding:18rpx 22rpx}.intro{display:flex;align-items:center;justify-content:space-between;padding:26rpx;border-radius:20rpx;background:linear-gradient(135deg,#16b990,#50d1b3);color:#fff}.intro text,.intro small{display:block}.intro text{font-size:30rpx;font-weight:700}.intro small{margin-top:8rpx;font-size:20rpx;opacity:.88}.intro button{height:58rpx;margin:0;padding:0 20rpx;border-radius:29rpx;background:#fff;color:#0fa981;font-size:21rpx;line-height:58rpx}.intro button::after{border:0}.card{margin-top:18rpx;padding:24rpx;border-radius:20rpx;background:#fff}.head{display:flex;justify-content:space-between}.head>text{font-size:24rpx;font-weight:700}.metrics{display:flex;margin-top:22rpx}.metrics view{display:flex;flex:1;flex-direction:column;align-items:center;border-right:1rpx solid #edf1f0}.metrics view:last-child{border-right:0}.metrics text{color:#8b9599;font-size:20rpx}.metrics strong{margin-top:7rpx;color:#28343a;font-size:28rpx}.time{margin-top:18rpx;color:#a0a9ad;font-size:20rpx}</style>
